#include <iostream>
#include <cstring>
#include <queue>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

using ll = long long;
using PII = pair<int, int>;

char board1[15][15], board2[15][15];
const int dr[4] = {-1, 1, 0, 0};
const int dc[4] = {0, 0, -1, 1};
int nodeID[65][15][15];
int distToZ[15][15];
int globalID = 1;

struct FlowNetwork {
    int V;
    struct Edge {
        int to;
        ll cap, flow;
        Edge(int t, ll c) : to(t), cap(c), flow(0) {}
    };
    vector<vector<Edge>> g;
    vector<int> lvl, cur;

    FlowNetwork(int n) : V(n), g(n), lvl(n), cur(n) {}

    void addEdge(int u, int v, ll c) {
        if (u == v) return;
        g[u].emplace_back(v, c);
        g[v].emplace_back(u, 0);
    }

    bool bfs(int s, int t) {
        fill(lvl.begin(), lvl.end(), V + 1);
        queue<int> q;
        q.push(s);
        lvl[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (u == t) break;
            for (auto &e : g[u]) {
                if (e.flow < e.cap && lvl[e.to] > lvl[u] + 1) {
                    lvl[e.to] = lvl[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return lvl[t] <= V;
    }

    ll dfs(int u, int t, ll f) {
        if (u == t || f == 0) return f;
        for (int &i = cur[u]; i < (int)g[u].size(); ++i) {
            auto &e = g[u][i];
            if (lvl[e.to] == lvl[u] + 1) {
                ll pushed = dfs(e.to, t, min(f, e.cap - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    g[e.to][find_if(g[e.to].begin(), g[e.to].end(), [&](const Edge &rev) {
                        return rev.to == u;
                    }) - g[e.to].begin()].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll maxFlow(int s, int t) {
        ll res = 0;
        while (bfs(s, t)) {
            fill(cur.begin(), cur.end(), 0);
            ll pushed;
            while ((pushed = dfs(s, t, 1e18)) > 0) {
                res += pushed;
            }
        }
        return res;
    }
};

int main() {
    memset(distToZ, -1, sizeof(distToZ));
    int n, T;
    cin >> n >> T;
    for (int i = 1; i <= n; ++i) {
        cin >> (board1[i] + 1);
    }
    for (int t = 0; t <= T + 1; ++t) {
        for (int r = 1; r <= n; ++r) {
            for (int c = 1; c <= n; ++c) {
                nodeID[t][r][c] = globalID++;
            }
        }
    }
    globalID++;
    for (int i = 1; i <= n; ++i) {
        cin >> (board2[i] + 1);
    }
    queue<PII> q;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (board1[i][j] == 'Z') {
                q.push({i, j});
                distToZ[i][j] = 0;
            }
        }
    }
    while (!q.empty()) {
        auto [y, x] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int ny = y + dr[d], nx = x + dc[d];
            if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && board1[ny][nx] != 'Y' && distToZ[ny][nx] == -1) {
                distToZ[ny][nx] = distToZ[y][x] + 1;
                q.push({ny, nx});
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (distToZ[i][j] == -1) distToZ[i][j] = INT_MAX;
            if (distToZ[i][j] > T) distToZ[i][j] = INT_MAX;
        }
    }
    int src = 0, dst = globalID - 1;
    FlowNetwork net(globalID);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (board1[i][j] >= '1' && board1[i][j] <= '9') {
                net.addEdge(src, nodeID[0][i][j], board1[i][j] - '0');
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (board1[i][j] == 'Y' || board1[i][j] == 'Z') continue;
            for (int d = 0; d < 4; ++d) {
                int ny = i + dr[d], nj = j + dc[d];
                if (ny >= 1 && ny <= n && nj >= 1 && nj <= n && board1[ny][nj] != 'Y' && board1[ny][nj] != 'Z') {
                    for (int step = 0; step < T; ++step) {
                        if (distToZ[ny][nj] >= step + 1 && distToZ[i][j] > step) {
                            net.addEdge(nodeID[step][i][j], nodeID[step + 1][ny][nj], 1000);
                        }
                    }
                }
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (board1[i][j] == 'Y' || board1[i][j] == 'Z') continue;
            for (int step = 0; step <= T; ++step) {
                if (board2[i][j] >= '1' && board2[i][j] <= '9') {
                    net.addEdge(nodeID[step][i][j], nodeID[T + 1][i][j], board2[i][j] - '0');
                }
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (board1[i][j] == 'Y' || board1[i][j] == 'Z') continue;
            if (board2[i][j] >= '1' && board2[i][j] <= '9') {
                net.addEdge(nodeID[T + 1][i][j], dst, board2[i][j] - '0');
            }
        }
    }
    cout << (int)net.maxFlow(src, dst) << '\n';
    return 0;
}
